<span class="line"><span style="color:#D73A49;">    let</span><span style="color:#24292E;"> val </span><span style="color:#D73A49;">=</span><span style="color:#6F42C1;"> fn</span><span style="color:#24292E;">(</span><span style="color:#D73A49;">...</span><span style="color:#24292E;">args);</span></span>
